import showsList from "../components/showsList"

export function addShow(show) {
    return {
        type: "ADD_SHOW",
        payload: show
    }
}

export function deleteShow(show) {
    return{
        type: "DELETE_SHOW",
        payload: show
    }
}

function showReducer(show1 = showsList, action) {
    console.log(show1)
    switch(action.type) {
        case "ADD_SHOW":
            return [...show1, action.payload]
        case "DELETE_SHOW": {
            const updatedArr = show1.filter(show => show.toLowerCase() !==
            action.payload.toLowerCase())
            return updatedArr
    }
        default: 
            return show1
    }
}

export default showReducer
